22	/**
23	 * @file stream_dup.hpp
24	 * @brief duplicate stream and attach end signal to each dup.
25	 *
26	 * This file is part of Vitis Utility Library.
27	 */
28	
29	// Forward decl ======================================================
30	
31	namespace xf {
32	namespace common {
33	namespace utils_hw {
34	
35	/**
36	 * @brief Duplicate stream.
37	 *
38	 * @tparam _TIn input stream width.
39	 * @tparam _NStrm number of output stream.
40	 *
41	 * @param istrm input data stream.
42	 * @param e_istrm end flag stream for input data.
43	 * @param ostrms output data streams.
44	 * @param e_ostrms end flag streams, one for each output data stream.
45	 */
46	template <typename _TIn, int _NStrm>
47	void streamDup(hls::stream<_TIn>& istrm,
48	               hls::stream<bool>& e_istrm,
49	               hls::stream<_TIn> ostrms[_NStrm],
50	               hls::stream<bool> e_ostrms[_NStrm]);
51	
52	/**
53	 * @brief Duplicate stream.
54	 *
55	 * @tparam _TIn input stream width.
56	 * @tparam _NIStrm number of input stream.
57	 * @tparam _NDStrm number of streams to be duplicated. Should be smaller than
58	 * _NIStrm.
59	 * @tparam _NDCopy number of copies of duplicated streams to be generated
60	 *
61	 * @param choose option to choose which input streams will be duplicated and
62	 * configure the order of the out duplicated streams.
63	 * @param istrm input data stream.
64	 * @param e_istrm end flag stream for input data.
65	 * @param ostrms output data streams.
66	 * @param dstrms output duplicated streams.
67	 * @param e_ostrms end flag streams.
68	 */
69	template <typename _TIn, int _NIStrm, int _NDStrm, int _NDCopy>
70	void streamDup(const unsigned int choose[_NDStrm],
71	               hls::stream<_TIn> istrm[_NIStrm],
72	               hls::stream<bool>& e_istrm,
73	               hls::stream<_TIn> ostrms[_NIStrm],
74	               hls::stream<_TIn> dstrms[_NDCopy][_NDStrm],
75	               hls::stream<bool>& e_ostrms);
76	
77	} // utils_hw
78	} // common
79	} // xf
80	
81	// Implementation ====================================================
82	
83	namespace xf {
84	namespace common {
85	namespace utils_hw {
86	
87	template <typename _TIn, int _NStrm>
88	void streamDup(hls::stream<_TIn>& istrm,
89	               hls::stream<bool>& e_istrm,
90	               hls::stream<_TIn> ostrms[_NStrm],
91	               hls::stream<bool> e_ostrms[_NStrm]) {
92	    bool e = e_istrm.read();
93	    while (!e) {
94	#pragma HLS pipeline II = 1
95	        _TIn tmp;
96	        e = e_istrm.read();
97	        tmp = istrm.read();
98	        for (int i = 0; i < _NStrm; i++) {
99	#pragma HLS unroll
100	            ostrms[i].write(tmp);
101	            e_ostrms[i].write(0);
102	        }
103	    }
104	    for (int i = 0; i < _NStrm; i++) {
105	#pragma HLS unroll
106	        e_ostrms[i].write(1);
107	    }
108	}
109	
110	template <typename _TIn, int _NIStrm, int _NDStrm, int _NDCopy>
111	void streamDup(const unsigned int choose[_NDStrm],
112	               hls::stream<_TIn> istrm[_NIStrm],
113	               hls::stream<bool>& e_istrm,
114	               hls::stream<_TIn> ostrms[_NIStrm],
115	               hls::stream<_TIn> dstrms[_NDCopy][_NDStrm],
116	               hls::stream<bool>& e_ostrms) {
117	    XF_UTILS_HW_STATIC_ASSERT(_NDStrm <= _NIStrm, "stream_dup cannot have more duplicated output than input.");
118	
119	    bool e = e_istrm.read();
120	    int i;
121	    while (!e) {
122	#pragma HLS PIPELINE II = 1
123	
124	        _TIn tmp[_NIStrm];
125	        for (i = 0; i < _NIStrm; i++) {
126	#pragma HLS UNROLL
127	            tmp[i] = istrm[i].read();
128	        }
129	
130	        for (i = 0; i < _NDStrm; i++) {
131	#pragma HLS UNROLL
132	            for (int j = 0; j < _NDCopy; j++) {
133	#pragma HLS UNROLL
134	                dstrms[j][i].write(tmp[choose[i]]);
135	            }
136	        }
137	
138	        for (i = 0; i < _NIStrm; i++) {
139	#pragma HLS UNROLL
140	            ostrms[i].write(tmp[i]);
141	        }
142	        e = e_istrm.read();
143	        e_ostrms.write(false);
144	    }
145	    e_ostrms.write(true);
146	}
147	
148	} // utils_hw
149	} // common
150	} // xf
151	
152	#endif // XF_UTILS_HW_STREAM_DUP_H
